INSERT INTO `model_hierarchy` VALUES ('FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp','meta-llama/Llama-3.1-8B-Instruct','adapterTrainedFrom',1,2,'{\"unknown\": [\"independent security evaluation results in the repository excerpt\", \"full data-generation provenance\"], \"retained\": [\"all base weights remain external to the adapter\", \"base tokenizer\"], \"added_security_goal\": \"resistance to prompt-injection attacks\", \"added_training_data\": [{\"name\": \"synthetic_alpaca\", \"size\": 19157, \"features\": [\"self-generated chosen/rejected responses\", \"randomly positioned adversarial instructions\"]}], \"adapter_configuration\": {\"rank\": 32, \"alpha\": 8, \"target_modules\": [\"q_proj\", \"v_proj\", \"gate_proj\", \"up_proj\", \"down_proj\"]}, \"added_training_method\": \"DPO via SecAlign++\", \"operational_dependency\": \"Must be loaded on top of meta-llama/Llama-3.1-8B-Instruct using PEFT.\", \"training_hyperparameters\": {\"epochs\": 3, \"dpo_beta\": 0.1, \"batch_size\": 1, \"learning_rate\": 0.00016, \"gradient_accumulation_steps\": 16}}','2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('FreedomIntelligence/HuatuoGPT-o1-8B','meta-llama/Llama-3.1-8B-Instruct','domainFineTunedAndReinforcementOptimizedFrom',1,0,'{\"unknown\": [\"full SFT/PPO hyperparameters for the released 8B artifact in the model card\", \"exact repository revision and artifact hashes\"], \"known_risk\": \"Medical outputs require expert validation and must not be treated as clinical advice.\", \"added_domain\": \"medicine\", \"added_training_data\": [{\"name\": \"medical-o1-verifiable-problem\", \"size\": \"40K final verifiable medical problems\", \"processing\": [\"difficulty filtering\", \"unique-answer filtering\", \"GPT-4o-assisted ambiguity filtering\", \"conversion to open-ended problems\"], \"source_pool\": \"192K medical multiple-choice questions\", \"derived_from\": [\"MedQA-USMLE training set\", \"MedMCQA training set\"]}, {\"name\": \"medical-o1-reasoning-SFT\", \"generation\": \"reasoning trajectories synthesized through search and verifier feedback\"}], \"added_external_models\": [{\"role\": \"reasoning trajectory generator and medical verifier\", \"model\": \"GPT-4o\"}], \"added_output_protocol\": [\"## Thinking\", \"## Final Response\"], \"added_training_methods\": [\"SFT on verifier-guided complex reasoning trajectories\", \"PPO with verifier-based sparse rewards\"], \"modified_primary_purpose\": \"general assistant -> medical reasoning model\", \"added_capabilities_claimed\": [\"complex medical reasoning\", \"iterative reflection and correction\", \"thinks-before-it-answers output\"]}','2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('HPAI-BSC/Qwen2.5-7B-Instruct-Egida-DPO','Qwen/Qwen2.5-7B-Instruct','preferenceOptimizedFrom',1,0,'{\"unknown\": [\"long-run behavioral tradeoffs beyond the published safety and refusal metrics\"], \"known_risk\": \"Refusal ratio rises on some benchmarks even while attack success falls.\", \"added_evaluation\": {\"delphi_asr\": \"0.118 vs 0.138 on the parent model\", \"alert_adv_asr\": \"0.045 vs 0.080 on the parent model\", \"egida_test_asr\": \"0.322 vs 0.471 on the parent model\"}, \"added_security_goal\": \"reduced jailbreak success and safer responses under adversarial prompting\", \"added_training_data\": [{\"name\": \"Egida-DPO-Qwen2.5-7B-Instruct\", \"role\": \"custom DPO dataset built from Egida adversarial prompts and chosen/rejected answers\"}], \"added_training_method\": \"DPO safety retrofitting on Egida triplets\", \"modified_primary_purpose\": \"general instruct assistant -> jailbreak-resistant instruct assistant\"}','2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge','meta-llama/Llama-3.1-8B-Instruct','taskFineTunedFrom',1,1,'{\"unknown\": [\"complete training hyperparameters in this extraction\", \"artifact hashes and immutable HF revision\"], \"added_task\": \"LLM-as-a-Judge for truthfulness assessment\", \"added_languages\": [\"English\", \"Basque\", \"Catalan\", \"Galician\", \"Spanish\"], \"inherited_risks\": [\"base-model biases\", \"TruthfulQA-derived benchmark biases\"], \"added_evaluation\": {\"primary_metric\": \"Spearman correlation with human truthfulness judgments\", \"additional_reported_metric\": \"language-specific Kappa\"}, \"added_training_data\": [{\"name\": \"HiTZ/truthful_judge\", \"role\": \"multilingual truthfulness judge fine-tuning\"}], \"removed_or_out_of_scope\": [\"general-purpose dialogue generation\", \"direct factual answering\", \"unvalidated safety-critical use\"], \"modified_primary_purpose\": \"general assistant -> multilingual truthfulness evaluator\"}','2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('NousResearch/Hermes-3-Llama-3.1-8B','meta-llama/Llama-3.1-8B','instructionTunedFrom',1,0,'{\"unknown\": [\"complete training dataset inventory\", \"complete dataset mixture ratios\", \"training compute\", \"exact artifact checksums in this extraction\"], \"retained\": [\"Llama 3.1 8B Transformer backbone\", \"8B parameter scale\"], \"added_prompt_protocol\": \"ChatML with added turn/role special tokens\", \"modified_primary_purpose\": \"base language model -> generalist instruct/tool-use assistant\", \"added_capabilities_claimed\": [\"generalist instruction following\", \"advanced agentic behavior\", \"function calling\", \"JSON/structured output\", \"roleplaying\", \"multi-turn conversation\", \"long-context coherence\", \"improved code generation\"], \"added_data_characteristics\": [\"synthetic data\", \"distillation-oriented data\"]}','2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('Qwen/Qwen2.5-7B',NULL,NULL,0,0,NULL,'2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('Qwen/Qwen2.5-7B-Instruct',NULL,NULL,0,1,NULL,'2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('Qwen/Qwen2.5-7B-Instruct-1M','Qwen/Qwen2.5-7B','contextExtendedFrom',1,0,'{\"unknown\": [\"model card metadata lists base_model as Qwen/Qwen2.5-7B while the card describes an instruct long-context variant\", \"exact training recipe used to reach the 1M context window\"], \"retained\": [\"7.61B architecture\", \"RoPE, SwiGLU, RMSNorm, and QKV-bias design\", \"8192-token generation limit\"], \"modified_primary_purpose\": \"base checkpoint -> ultra-long-context instruct-style 1M-token model\", \"added_operational_feature\": \"custom vLLM sparse attention and length extrapolation guidance for ultra-long inputs\", \"added_capabilities_claimed\": [\"up to 1M-token context handling\", \"better long-context task performance\", \"short-task capability retention\"]}','2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('mellee030/MedQwen-7B-LoRA','Qwen/Qwen2.5-7B-Instruct','adapterTrainedFrom',1,1,'{\"retained\": [\"base model general capabilities\", \"Qwen2.5 chat template compatibility\"], \"added_domain\": \"Chinese medical question answering\", \"added_evaluation\": {\"note\": \"ROUGE is lower because the adapter favors concise on-format answers\", \"bertscore\": \"0.6670 vs 0.5959 on the base comparison\"}, \"added_training_data\": [{\"name\": \"30,284 Chinese medical dialogue pairs\", \"role\": \"medical Q&A adaptation\", \"processing\": [\"converted to the Qwen2.5 chat template format\"]}], \"adapter_configuration\": {\"rank\": 8, \"alpha\": 16}, \"added_training_method\": \"LoRA PEFT fine-tuning\", \"modified_primary_purpose\": \"general instruct assistant -> Chinese medical dialogue adapter\"}','2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('meta-llama/Llama-3.1-8B',NULL,NULL,0,0,NULL,'2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('meta-llama/Llama-3.1-8B-Instruct',NULL,NULL,0,1,NULL,'2026-09-26 09:52:39.909709','2026-09-26 09:52:39.909709'),('mlx-community/Meta-Llama-3.1-8B-Instruct-bf16','meta-llama/Llama-3.1-8B-Instruct','convertedFrom',1,3,'{\"unknown\": [\"conversion command and flags\", \"numerical equivalence tests\", \"artifact checksums and immutable revision\