INSERT INTO `provenance` VALUES (361,'dataset:slug:synthetic_alpaca','Cleaned Alpaca Dataset','FAIR at Meta / UC Berkeley (SecAlign++ recipe authors), derived from gururise/AlpacaDataCleaned','[\"dataset:slug:cleaned-alpaca\"]','generated_from','[1, 2, 650]','{\"disclosure_status\": \"partially_disclosed\"}'),(362,'dataset:slug:cleaned-alpaca',NULL,'Gene Ruebsamen (community)',NULL,'original','[1, 649]','{\"disclosure_status\": \"disclosed\"}'),(363,'dataset:GBaker/MedQA-USMLE-4-options',NULL,'Original MedQA authors (Jin et al.); training set reused by FreedomIntelligence',NULL,'original','[4]','{\"disclosure_status\": \"disclosed\"}'),(364,'dataset:openlifescienceai/medmcqa',NULL,'Original MedMCQA authors; training set reused by FreedomIntelligence',NULL,'original','[4]','{\"disclosure_status\": \"disclosed\"}'),(365,'dataset:FreedomIntelligence/medical-o1-verifiable-problem','MedQA-USMLE (training set), MedMCQA (training set)','FreedomIntelligence','[\"dataset:GBaker/MedQA-USMLE-4-options\", \"dataset:openlifescienceai/medmcqa\"]','derived_from','[4, 6]','{\"disclosure_status\": \"disclosed\"}'),(366,'dataset:FreedomIntelligence/medical-o1-reasoning-SFT','MedQA-USMLE (training set), MedMCQA (training set)','FreedomIntelligence','[\"dataset:FreedomIntelligence/medical-o1-verifiable-problem\"]','generated_from','[4, 8]','{\"disclosure_status\": \"disclosed\"}'),(367,'dataset:qiaojin/PubMedQA',NULL,NULL,NULL,'original',NULL,'{\"disclosure_status\": \"disclosed\"}'),(368,'dataset:TIGER-Lab/MMLU-Pro',NULL,'third-party academic benchmark authors',NULL,'original','[29]','{\"disclosure_status\": \"disclosed\"}'),(370,'dataset:HiTZ/truthful_judge','TruthfulQA','HiTZ Center - Ixa, University of the Basque Country (UPV/EHU) and collaborators','[\"dataset:truthfulqa/truthful_qa\"]','derived_from','[10, 11]','{\"disclosure_status\": \"disclosed\"}'),(371,'dataset:truthfulqa/truthful_qa',NULL,'Stephanie Lin, Jacob Hilton, Owain Evans',NULL,'original','[10, 11, 29]','{\"disclosure_status\": \"disclosed\"}'),(372,'dataset:slug:llama-3.1-pretraining-mixture',NULL,'Meta',NULL,'original','[14, 22, 24]','{\"disclosure_status\": \"undisclosed\"}'),(373,'dataset:HPAI-BSC/Egida',NULL,'HPAI-BSC',NULL,'original','[15, 16]','{\"disclosure_status\": \"disclosed\"}'),(374,'dataset:slug:egida-s','Egida','HPAI-BSC','[\"dataset:HPAI-BSC/Egida\"]','derived_from','[15]','{\"disclosure_status\": \"disclosed\"}'),(375,'dataset:slug:egida-dpo-qwen2.5-7b-instruct','Egida','HPAI-BSC','[\"dataset:HPAI-BSC/Egida\", \"dataset:slug:egida-s\"]','derived_from','[15, 16, 19]','{\"disclosure_status\": \"disclosed\"}'),(377,'dataset:slug:or-bench-80k',NULL,'OR-Bench paper authors (Cui et al.)',NULL,'original','[648]','{\"disclosure_status\": \"disclosed\"}'),(378,'dataset:slug:medqwen-7b-lora-chinese-medical-dialogue-30284',NULL,'mellee030',NULL,'original','[21]','{\"disclosure_status\": \"partially_disclosed\"}'),(379,'dataset:slug:llama-3.1-post-training-data',NULL,'Meta',NULL,'original','[22]','{\"disclosure_status\": \"undisclosed\"}'),(380,'dataset:google/IFEval',NULL,'third-party academic benchmark authors',NULL,'original','[29]','{\"disclosure_status\": \"disclosed\"}'),(381,'dataset:allenai/ai2_arc',NULL,'third-party academic benchmark authors',NULL,'original','[29]','{\"disclosure_status\": \"disclosed\"}'),(382,'dataset:openai/openai_humaneval',NULL,'third-party academic benchmark authors',NULL,'original','[29]','{\"disclosure_status\": \"disclosed\"}'),(383,'dataset:google-research-datasets/mbpp',NULL,'third-party academic benchmark authors',NULL,'original','[29]','{\"disclosure_status\": \"disclosed\"}'),(384,'dataset:slug:multipl-e',NULL,'Northeastern University Programming Research Lab (nuprl)',NULL,'original','[640]','{\"disclosure_status\": \"disclosed\"}'),(385,'dataset:openai/gsm8k',NULL,'third-party academic benchmark authors',NULL,'original','[29]','{\"disclosure_status\": \"disclosed\"}'),(386,'dataset:hendrycks/competition_math',NULL,'third-party academic benchmark authors',NULL,'original','[29]','{\"disclosure_status\": \"disclosed\"}'),(387,'dataset:slug:api-bank',NULL,'Alibaba (API-Bank paper authors)',NULL,'original','[644]','{\"disclosure_status\": \"disclosed\"}'),(388,'dataset:slug:bfcl',NULL,'UC Berkeley Gorilla LLM project (Sky Computing Lab)',NULL,'original','[645]','{\"disclosure_status\": \"disclosed\"}'),(389,'dataset:slug:gorilla-api-bench',NULL,'UC Berkeley (Shishir G. Patil, Tianjun Zhang, Xin Wang, Joseph E. Gonzalez - Gorilla project)',NULL,'original','[646]','{\"disclosure_status\": \"disclosed\"}'),(390,'dataset:slug:nexus',NULL,'Nexusflow',NULL,'original','[647]','{\"disclosure_status\": \"disclosed\"}'),(391,'dataset:slug:mgsm',NULL,'Google Research',NULL,'original','[639]','{\"disclosure_status\": \"disclosed\"}'),(392,'dataset:slug:agieval-english',NULL,'Ruixiang Cui et al. (Microsoft Research / Westlake University)',NULL,'original','[486]','{\"disclosure_status\": \"disclosed\"}'),(393,'dataset:slug:commonsenseqa',NULL,'Tel Aviv University / Allen Institute for AI',NULL,'original','[488]','{\"disclosure_status\": \"disclosed\"}'),(394,'dataset:allenai/winogrande',NULL,'third-party academic benchmark authors',NULL,'original','[29, 484]','{\"disclosure_status\": \"disclosed\"}'),(395,'dataset:lukaemon/bbh',NULL,'third-party academic benchmark authors',NULL,'original','[29, 485]','{\"disclosure_status\": \"disclosed\"}'),(396,'dataset:slug:triviaqa-wiki',NULL,'University of Washington',NULL,'original','[643]','{\"disclosure_status\": \"disclosed\"}'),(397,'dataset:slug:squad',NULL,'Stanford University',NULL,'original','[642]','{\"disclosure_status\": \"disclosed\"}'),(398,'dataset:slug:quac',NULL,'Allen Institute for AI (AI2)',NULL,'original','[641]','{\"disclosure_status\": \"disclosed\"}'),(399,'dataset:slug:boolq',NULL,'Google Research',NULL,'original','[487]','{\"disclosure_status\": \"disclosed\"}'),(400,'dataset:slug:drop',NULL,'University of California, Irvine (UCI NLP)',NULL,'original','[638]','{\"disclosure_status\": \"disclosed\"}'),(401,'dataset:slug:hermes-3-sft-mixture',NULL,'Nous Research',NULL,'original','[25]','{\"disclosure_status\": \"partially_disclosed\"}'),(402,'dataset:NousResearch/hermes-function-calling-v1',NULL,'Nous Research',NULL,'original','[25]','{\"disclosure_status\": \"disclosed\"}'),(403,'dataset:slug:hermes-3-dpo-preference-data',NULL,'Nous Research',NULL,'original','[25]','{\"disclosure_status\": \"undisclosed\"}'),(404,'dataset:Rowan/hellaswag',NULL,'third-party academic benchmark authors',NULL,'original','[29, 483]','{\"disclosure_status\": \"disclosed\"}'),(405,'dataset:slug:qwen2.5-1m-long-context-synthesis',NULL,'Qwen Team (Alibaba Cloud)',NULL,'original','[28]','{\"disclosure_status\": \"partially_disclosed\"}'),(406,'dataset:slug:qwen2.5-pretraining-corpus',NULL,'Qwen Team (Alibaba Cloud)',NULL,'original','[29, 30]','{\"disclosure_status\": \"undisclosed\"}'),(407,'dataset:slug:qwen2.5-post-training-mixture','Qwen2.5 pretraining corpus','Qwen Team (Alibaba Cloud)','[\"dataset:slug:qwen2.5-pretraining-corpus\"]','derived_from','[29, 30]','{\"disclosure_status\": \"partially_disclosed\"}'),(408,'model:FlorianJK/Meta-Llama-3.1-8B-SecAlign-pp','Meta Llama 3.1','FlorianJK (independent/community reproduction of the Meta SecAlign \'SecAlign++\' training recipe)','[\"model:meta-llama/Llama-3.1-8B-Instruct\"]','adapter_trained_from','[1, 2, 55, 59]','{\"notes\": \"This LoRA adapter reproduces the SecAlign++ defensive fine-tuning recipe described in arXiv:2507.02735 (Meta SecAlign), applied to meta-llama/Llama-3.1-8B-Instruct. It is not the official Meta/FAIR checkpoint; the official releases are facebook/Meta-SecAlign-8B and facebook/Meta-SecAlign-70B. A companion \'SecUnalign-pp\' adapter with inverted preferences is also referenced in the card for red-teaming purposes.\", \"disclosure_status\": \"partially_disclosed\"}'),(410,'model:HiTZ/Llama-3.1-8B-Instruct-multi-truth-judge','Meta Llama 3.1','HiTZ Center - Ixa (UPV/EHU) and collaborators (Elhuyar, CiTIUS/USC, Universitat Pompeu Fabra)','[\"model:meta-llama/Llama-3.1-8B-Instruct\"]','fine_tuned_from','[11, 14]','{\"notes\": \"Fine-tuned from meta-llama/Meta-Llama-3.1-8B-Instruct to act as an LLM-as-a-Judge for truthfulness, as part of the \'Truth Knows No Language\' project (TruthfulQA-Multi). Base model weights/license remain Llama 3.1 Community License; this model\'s weights, fine-tuning code, and training dataset are released under Apache-2.0.\", \"disclosure_status\": \"partially_disclosed\"}'),(411,'model:HPAI-BSC/Qwen2.5-7B-Instruct-Egida-DPO','Qwen2.5','HPAI-BSC (Barcelona Supercomputing Center, High Performance Artificial Intelligence group)','[\"model:Qwen/Qwen2.5-7B-Instruct\"]','preference_optimized_from','[16, 19, 77]','{\"notes\": \"Model card declares base_model Qwen/Qwen2.5-7B-Instruct and dataset HPAI-BSC/Egida; both the safety-retrofitting method and dataset construction are described in the accompanying paper (arXiv:2502.13603).\", \"disclosure_status\": \"disclosed\"}'),(412,'model:mellee030/MedQwen-7B-LoRA','Qwen2.5','mellee030','[\"model:Qwen/Qwen2.5-7B-Instruct\"]','adapter_trained_from','[21, 83]','{\"notes\": \"Personal/community LoRA fine-tune of Qwen/Qwen2.5-7B-Instruct. Author identity beyond the HF handle \'mellee030\' (linked GitHub user \'melc030\') and any organizational affiliation are not disclosed. base_model_name_or_path in adapter_config.json points to a local path (\'/home/yuxincui/MedQwen/Qwen2.5-7B-Instruct\'), consistent with a local copy of the public Qwen/Qwen2.5-7B-Instruct checkpoint rather than a modified base.\", \"disclosure_status\": \"partially_disclosed\"}'),(413,'model:meta-llama/Llama-3.1-8B-Instruct','Meta Llama 3.1','Meta','[\"model:meta-llama/Llama-3.1-8B\"]','instruction_tuned_from','[22, 89]','{\"notes\": \"HF metadata for meta-llama/Llama-3.1-8B-Instruct declares base_model: meta-llama/Llama-3.1-8B and base_model:finetune relation. Meta discloses the post-training pipeline (SFT -> rejection sampling -> DPO, iterated over multiple rounds, plus model averaging) but not exact hyperparameters or full data provenance for the 8B-specific run.\", \"disclosure_status\": \"partially_disclosed\"}'),(414,'model:meta-llama/Llama-3.1-8B','Meta Llama 3.1','Meta',NULL,'pretrained','[22, 24]','{\"notes\": \"Meta discloses pretraining stages (initial pre-training, long-context continued pre-training, annealing) and high-level data-processing steps, corpus scale (~15T tokens), and cutoff (Dec 2023), but does not release an exact dataset inventory or mixture ratios.\", \"disclosure_status\": \"partially_disclosed\"}'),(415,'model:mlx-community/Meta-Llama-3.1-8B-Instruct-bf16','Meta Llama 3.1','mlx-community','[\"model:meta-llama/Llama-3.1-8B-Instruct\"]','converted_from','[102]','{\"notes\": \"The mlx-community card states this repo was converted to MLX format from meta-llama/Llama-3.1-8B-Instruct using mlx-lm version 0.19.0. Weights are kept at BF16 precision; no additional training, fine-tuning, or dataset use is reported. Repo created 2024-07-23, same day as the Llama 3.1 release.\", \"disclosure_status\": \"disclosed\"}'),(416,'model:mlx-community/Qwen2.5-7B-Instruct-bf16','Qwen2.5','mlx-community','[\"model:Qwen/Qwen2.5-7B-Instruct\"]','converted_from','[110]','{\"notes\": \"The mlx-community card states this repo was converted to MLX format from Qwen/Qwen2.5-7B-Instruct using mlx-lm version 0.18.1. Weights are kept at BF16 precision; no additional training, fine-tuning, or dataset use is reported. Repo created 2024-09-18, immediately after the Qwen2.5 release (2024-09-19).\", \"disclosure_status\": \"disclosed\"}'),(417,'model:NousResearch/Hermes-3-Llama-3.1-8B','Meta Llama 3.1','Nous Research','[\"model:meta-llama/Llama-3.1-8B\"]','instruction_tuned_from','[25, 119, 120]','{\"notes\": \"Hermes 3 8B is created by supervised fine-tuning followed by LoRA-based DPO on top of the Llama 3.1 8B base model (config.json base is meta-llama/Meta-Llama-3.1-8B / meta-llama/Llama-3.1-8B). Exact per-sample dataset inventory is not published; only category proportions and token counts are disclosed in the technical report.\", \"disclosure_status\": \"partially_disclosed\"}'),(418,'model:Qwen/Qwen2.5-7B-Instruct-1M','Qwen2.5','Qwen Team (Alibaba Cloud)','[\"model:Qwen/Qwen2.5-7B\"]','context_extended_from','[28, 128, 130, 132]','{\"notes\": \"The HF card\'s base_model field declares Qwen/Qwen2.5-7B (the released 128K-context base checkpoint), but the Qwen2.5-1M Technical Report states the 1M-context series was actually built from \'an intermediate checkpoint of pre-trained Qwen2.5\' that still had only a 4K-token context length, i.e. an internal, unreleased pretraining checkpoint predating the public Qwen2.5-7B release, not the released Qwen2.5-7B artifact itself. From that intermediate checkpoint the model underwent 5 stages of progressive long-context pretraining (4K->32K->65,536->131,072->262,144 tokens; RoPE base raised 10,000->10,000,000), then a 2-stage long-context SFT (short sequences up to 32K, then mixed short/long up to 262K), then offline reinforcement learning on short (<=8K token) samples. The exact identity/weights of that intermediate checkpoint were not released, so it cannot be cited as a separate HF model_id.\", \"disclosure_status\": \"partially_disclosed\"}'),(419,'model:Qwen/Qwen2.5-7B-Instruct','Qwen2.5','Qwen Team (Alibaba Cloud)','[\"model:Qwen/Qwen2.5-7B\"]','instruction_tuned_from','[29, 30, 81]','{\"notes\": \"HF model card YAML front-matter declares base_model: Qwen/Qwen2.5-7B. The technical report discloses that post-training used supervised fine-tuning with over 1M samples plus multistage reinforcement learning, but does not disclose the exact SFT/RL dataset composition.\", \"disclosure_status\": \"partially_disclosed\"}'),(420,'model:Qwen/Qwen2.5-7B','Qwen2.5','Qwen Team (Alibaba Cloud)',NULL,'pretrained','[29, 30, 139, 140]','{\"notes\": \"HF model card and config.json disclose architecture and parameter counts; the technical report discloses aggregate pretraining token count (up to 18T tokens) and high-level data composition (general text, code, math, multilingual) but not the exact source/dataset inventory.\", \"disclosure_status\": \"partially_disclosed\"}'),(421,'model:FreedomIntelligence/HuatuoGPT-o1-8B','Meta Llama 3.1','FreedomIntelligence','[\"model:meta-llama/Llama-3.1-8B-Instruct\"]','fine_tuned_from','[4, 62]','{\"notes\": \"HF cardData declares base_model: meta-llama/Llama-3.1-8B-Instruct with a base_model:finetune relation tag. The paper fully discloses the two-stage training method (SFT then PPO-based RL) and the data-construction pipeline, but does not disclose exact code/infra, full compute budget, or the released checkpoint\'s exact commit-level training log.\", \"disclosure_status\": \"partially_disclosed\"}'),(425,'dataset:slug:gpt-oss-pretraining-mixture',NULL,'OpenAI','[]','original','[1069]','{\"disclosure_status\": \"partially_disclosed\"}'),(426,'dataset:slug:gpt-oss-posttraining-mixture',NULL,'OpenAI','[]','original','[1069, 1070]','{\"disclosure_status\": \"partially_disclosed\"}'),(427,'dataset:Idavidrein/gpqa',NULL,NULL,'[]','original','[1069]','{\"disclosure_status\": \"disclosed\"}'),(428,'dataset:cais/mmlu',NULL,NULL,'[]','original','[1069]','{\"disclosure_status\": \"disclosed\"}'),(429,'dataset:cais/hle',NULL,'Center for AI Safety and Scale AI','[]','original','[1069, 1072]','{\"disclosure_status\": \"disclosed\"}'),(430,'dataset:openai/healthbench',NULL,'OpenAI','[]','original','[1069, 1073]','{\"disclosure_status\": \"disclosed\"}'),(431,'dataset:openai/MMMLU',NULL,'OpenAI','[\"dataset:cais/mmlu\"]','translated_from','[1069, 1074]','{\"disclosure_status\": \"disclosed\"}'),(432,'dataset:slug:gpt-oss-posttraining-problem-mixture',NULL,'OpenAI','[]','original','[1069]','{\"disclosure_status\": \"partially_disclosed\"}'),(433,'model:openai/gpt-oss-120b','GPT-OSS','OpenAI','[]','pretrained','[1065, 1069, 1070]','{\"notes\": \"The model card describes pretraining followed by reasoning and tool-use post-training, but does not identify a separate released base checkpoint or a direct external weight parent.\", \"disclosure_status\": \"partially_disclosed\"}');
