/*!50001 VIEW `v_model_evaluation` AS select `e`.`model` AS `model_id`,json_unquote(json_extract(`e`.`configuration`,'$.benchmark')) AS `benchmark`,`e`.`metric` AS `metric`,`e`.`score` AS `score`,json_unquote(json_extract(`e`.`extensions`,'$.score_text')) AS `score_text`,json_unquote(json_extract(`e`.`extensions`,'$.baseline_model')) AS `baseline_model`,cast(nullif(json_unquote(json_extract(`e`.`extensions`,'$.baseline_score')),'null') as decimal(14,4)) AS `baseline_score`,(`e`.`score` - cast(nullif(json_unquote(json_extract(`e`.`extensions`,'$.baseline_score')),'null') as decimal(14,4))) AS `delta_vs_baseline`,json_unquote(json_extract(`e`.`extensions`,'$.evaluator_model')) AS `evaluator_model`,`e`.`configuration` AS `configuration`,`e`.`dataset` AS `dataset_id`,json_unquote(json_extract(`d`.`extensions`,'$.name')) AS `dataset_name`,`e`.`timestamp` AS `timestamp`,json_unquote(json_extract(`e`.`extensions`,'$.reference')) AS `source_uri`,`e`.`id` AS `evaluation_id` from (`evaluation` `e` left join `dataset` `d` on((`d`.`identity` = `e`.`dataset`))) */;
